import { useIntl } from 'react-intl';

import { NoDataYet } from 'components';
import { Skeleton } from 'components/Skeleton/Skeleton';
import { usePageFilterApplied, useSubFilters } from 'hooks';
import {
  DeepDiveChartHeader,
  RankingChart,
} from 'pages/components/ConnectionsCreativity';

import { RESOURCE_ALLOCATION_MEDIA_PAGE_NAME } from '../../../../ResourceAllocationMedia';
import { StyledEmptyState } from '../../Overview.styles';
import { ResourceAllocationData } from '../../types';
import { getDeepDiveHeaderMessage, hasRankingChartData } from '../../utils';

interface RankingViewProps {
  data: ResourceAllocationData;
  loadingRanking: boolean;
  selectedView?: string;
  dataTestId?: string;
}

export const RankingView: React.FC<RankingViewProps> = ({
  data,
  loadingRanking,
  selectedView,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { isGlobalZone } = usePageFilterApplied(
    RESOURCE_ALLOCATION_MEDIA_PAGE_NAME,
  );
  const { activeSubFilters } = useSubFilters();

  const rankingHeaderMessage = getDeepDiveHeaderMessage({
    activeSubFilters,
    isGlobalZone,
    data,
    formatMessage,
    selectedView,
  });

  if (loadingRanking) {
    return (
      <Skeleton
        length={1}
        width="100%"
        height="450px"
        dataTestId={dataTestId ? `skeleton-${dataTestId}` : undefined}
      />
    );
  }

  const showRankingEmptyState = !hasRankingChartData(data);

  return (
    <>
      <DeepDiveChartHeader
        title={rankingHeaderMessage.title}
        measure={rankingHeaderMessage.measure}
        tooltip={rankingHeaderMessage.tooltip}
        dataTestId={
          dataTestId ? `${dataTestId}-ranking-view-header` : undefined
        }
      />

      {showRankingEmptyState ? (
        <StyledEmptyState
          data-testid={
            dataTestId ? `${dataTestId}-ranking-view-empty-state` : undefined
          }
          style={{ minHeight: '12rem', padding: '64px 24px' }}
        >
          <NoDataYet
            title={formatMessage({
              id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.emptyState.title',
            })}
            description={formatMessage({
              id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.emptyState.description',
            })}
            illustration="noDataAvailable"
            dataTestId={dataTestId ? `${dataTestId}-ranking-view` : undefined}
          />
        </StyledEmptyState>
      ) : (
        <RankingChart
          data={data}
          labelIconTooltip={rankingHeaderMessage.labelIconTooltip}
          horizontalDashedLineTooltip={
            rankingHeaderMessage.horizontalDashedLineTooltip
          }
          dataTestId={dataTestId}
        />
      )}
    </>
  );
};
